const crypto = require('crypto');
const secret = $env.HQ_SIGNING_SECRET || '';
if (!secret) throw new Error('no signing secret');
// tomorrow in Tehran: the day the post goes out (it is made today)
const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(Date.now() + 24 * 3600 * 1000));
const body = JSON.stringify({ day: parts });
const ts = Math.floor(Date.now() / 1000);
const mac = crypto.createHmac('sha256', secret).update(`${ts}.`).update(body).digest('hex');
// the hub's Idempotency-Key is a UUID: one made from the flow and the day (the same on a retry)
const h = crypto.createHash('sha256').update(`flow:prochart_reels:${parts}`).digest('hex');
const key = `${h.slice(0, 8)}-${h.slice(8, 12)}-5${h.slice(13, 16)}-${((parseInt(h[16], 16) & 3) | 8).toString(16)}${h.slice(17, 20)}-${h.slice(20, 32)}`;
return [{ json: { body, signature: `t=${ts},v1=${mac}`, key } }];
